// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/**
 * Unit spec for {@link LmdbNativeWork}, the work-interval currency, and for the {@code estimateWork} implementations
 * that let a plan be priced at all.
 * <p>
 * The single most important property here is that "unknown" is not "expensive". Before work intervals existed,
 * {@link SlotPlan#estimate} answered {@link Double#POSITIVE_INFINITY} for filters, OPTIONALs, unions and MINUS alike,
 * so any query containing one of those was unpriceable end to end — and a cost model that reads infinity as a cost
 * would rank every such plan last. These tests pin the replacement behaviour: an unknown interval simply declines to
 * take part in the comparison.
 */
public class LmdbNativeWorkTest {

	private static final int ROOT = 0;
	private static final int OTHER = 1;

	private static PatternPlan pattern(Term subject, long predicate, Term object, double estimate) {
		return new PatternPlan(subject, Term.constant(predicate), object, Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, estimate);
	}

	private static PatternPlan driver(double rows) {
		return pattern(Term.slot(ROOT), 7L, Term.constant(8L), rows);
	}

	// ---------------------------------------------------------------- interval algebra

	@Test
	public void unknownNeitherDominatesNorIsDominated() {
		LmdbNativeWork cheap = LmdbNativeWork.exact(1D);
		LmdbNativeWork expensive = LmdbNativeWork.exact(1_000_000D);

		assertThat(LmdbNativeWork.UNKNOWN.beats(cheap)).isFalse();
		assertThat(LmdbNativeWork.UNKNOWN.beats(expensive)).isFalse();
		assertThat(cheap.beats(LmdbNativeWork.UNKNOWN)).isFalse();
		assertThat(expensive.beats(LmdbNativeWork.UNKNOWN)).isFalse();
		assertThat(LmdbNativeWork.UNKNOWN.known()).isFalse();
	}

	@Test
	public void dominationIsStrictSoOverlappingIntervalsDoNotDecide() {
		LmdbNativeWork low = LmdbNativeWork.between(10D, 100D);
		LmdbNativeWork high = LmdbNativeWork.between(50D, 500D);
		LmdbNativeWork clear = LmdbNativeWork.between(200D, 300D);

		assertThat(low.beats(high)).as("overlapping intervals must not decide").isFalse();
		assertThat(high.beats(low)).isFalse();
		assertThat(low.beats(clear)).as("disjoint and below: this is the only case that decides").isTrue();
		assertThat(clear.beats(low)).isFalse();
	}

	@Test
	public void neverExecutedPlanCostsNothingEvenWhenUnpriceable() {
		assertThat(LmdbNativeWork.UNKNOWN.times(0D)).isEqualTo(LmdbNativeWork.ZERO);
		assertThat(LmdbNativeWork.exact(1_000D).times(0D)).isEqualTo(LmdbNativeWork.ZERO);
	}

	@Test
	public void malformedIntervalDegradesToUnknownRatherThanLying() {
		assertThat(new LmdbNativeWork(100D, 1D)).isEqualTo(LmdbNativeWork.UNKNOWN);
		assertThat(new LmdbNativeWork(-1D, 10D)).isEqualTo(LmdbNativeWork.UNKNOWN);
		assertThat(LmdbNativeWork.exact(Double.NaN)).isEqualTo(LmdbNativeWork.UNKNOWN);
		assertThat(LmdbNativeWork.exact(Double.POSITIVE_INFINITY)).isEqualTo(LmdbNativeWork.UNKNOWN);
	}

	@Test
	public void scalingAndAdditionStayInTheSameCurrency() {
		LmdbNativeWork one = LmdbNativeWork.exact(10D);
		assertThat(one.plus(LmdbNativeWork.exact(5D))).isEqualTo(LmdbNativeWork.exact(15D));
		assertThat(one.times(3D)).isEqualTo(LmdbNativeWork.exact(30D));
		assertThat(one.plus(LmdbNativeWork.UNKNOWN).known()).as("unknown is contagious upward").isFalse();
	}

	// ---------------------------------------------------------------- plan work

	@Test
	public void patternWorkIsOneSeekPlusItsRows() {
		PatternPlan plan = driver(10D);
		double rows = plan.estimateForBoundMask(0L, null);

		assertThat(plan.estimateWork(null, 0L)).isEqualTo(LmdbNativeWork.exact(LmdbNativeWork.SEEK + rows));
	}

	@Test
	public void filterOverAPatternIsPriceable() {
		PatternPlan arg = driver(10D);
		// The condition is never evaluated by the cost model, only counted, so a null filter is safe here.
		FilterPlan filter = new FilterPlan(arg, null, -1L);

		LmdbNativeWork work = filter.estimateWork(null, 0L);

		assertThat(work.known())
				.as("a filter used to make the whole enclosing plan unpriceable; that is the coverage this buys")
				.isTrue();
		double rows = arg.estimateForBoundMask(0L, null);
		assertThat(work).isEqualTo(LmdbNativeWork.exact(LmdbNativeWork.SEEK + rows + rows));
	}

	@Test
	public void unionSumsItsArms() {
		PatternPlan left = driver(10D);
		PatternPlan right = pattern(Term.slot(OTHER), 9L, Term.constant(8L), 20D);

		LmdbNativeWork work = new UnionPlan(left, right).estimateWork(null, 0L);

		assertThat(work).isEqualTo(left.estimateWork(null, 0L).plus(right.estimateWork(null, 0L)));
	}

	@Test
	public void joinPaysTheRightSideOncePerLeftRow() {
		PatternPlan left = driver(10D);
		PatternPlan right = pattern(Term.slot(ROOT), 9L, Term.slot(OTHER), 100D);

		LmdbNativeWork work = new JoinPlan(left, right).estimateWork(null, 0L);

		double leftRows = left.estimateForBoundMask(0L, null);
		LmdbNativeWork rightWork = right.estimateWork(null, left.producedMask());
		assertThat(work).isEqualTo(left.estimateWork(null, 0L).plus(rightWork.times(leftRows)));
		assertThat(work.high())
				.as("the right side is re-probed per left row, so its term must scale with the left cardinality")
				.isGreaterThanOrEqualTo(leftRows * rightWork.low());
	}

	@Test
	public void leftJoinCostsTheSameWorkAsAnInnerJoin() {
		PatternPlan left = driver(10D);
		PatternPlan right = pattern(Term.slot(ROOT), 9L, Term.slot(OTHER), 100D);

		assertThat(new LeftJoinPlan(left, right).estimateWork(null, 0L))
				.as("an OPTIONAL probes its right arm for every left row exactly like an inner join does; the arms "
						+ "differ in which rows they emit, not in the work spent finding them")
				.isEqualTo(new JoinPlan(left, right).estimateWork(null, 0L));
	}

	@Test
	public void terminalPlansAreFree() {
		assertThat(SlotPlan.empty().estimateWork(null, 0L)).isEqualTo(LmdbNativeWork.ZERO);
		assertThat(SlotPlan.singleton().estimateWork(null, 0L)).isEqualTo(LmdbNativeWork.ZERO);
	}

	@Test
	public void terminalPlanCardinalitiesAreKnownWithoutChangingEstimate() {
		assertThat(LmdbNativeWork.rowsOut(SlotPlan.empty(), null, 0L)).isEqualTo(0D);
		assertThat(LmdbNativeWork.rowsOut(SlotPlan.singleton(), null, 0L)).isEqualTo(1D);
		assertThat(SlotPlan.empty().estimate(null))
				.as("the legacy cardinality contract is deliberately left untouched")
				.isEqualTo(Double.POSITIVE_INFINITY);
	}

	@Test
	public void unpriceableChildMakesTheChainUnknownWithoutClaimingItIsExpensive() {
		PatternPlan known = driver(10D);
		// PathPlan and friends have no work model yet; a plain SlotPlan stand-in behaves the same way.
		SlotPlan unpriceable = new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				throw new UnsupportedOperationException();
			}

			@Override
			public long producedMask() {
				return 1L << OTHER;
			}
		};

		LmdbNativeWork.Chain chain = LmdbNativeWork.chain(new SlotPlan[] { known, unpriceable }, 2, null, 0L);

		assertThat(chain.known()).isFalse();
		assertThat(chain.work().known()).isFalse();
		assertThat(chain.work().beats(LmdbNativeWork.exact(Double.MAX_VALUE)))
				.as("an unpriceable chain must not be treated as cheap either")
				.isFalse();
		assertThat(LmdbNativeWork.exact(1D).beats(chain.work()))
				.as("nor may anything claim to beat it")
				.isFalse();
	}

	@Test
	public void chainAccumulatesBoundMaskAcrossChildren() {
		PatternPlan first = driver(10D);
		PatternPlan second = pattern(Term.slot(ROOT), 9L, Term.slot(OTHER), 5D);

		LmdbNativeWork.Chain chain = LmdbNativeWork.chain(new SlotPlan[] { first, second }, 2, null, 0L);

		assertThat(chain.known()).isTrue();
		assertThat(chain.boundMask()).isEqualTo(first.producedMask() | second.producedMask());
		assertThat(chain.rows()).isEqualTo(first.estimateForBoundMask(0L, null)
				* second.estimateForBoundMask(first.producedMask(), null));
	}
}
